import {esc} from '../editor/model.js';
import {icon} from '../../shared/icons.js';
const glyph=t=>t.status==='已完成'?'check':t.status==='失败'?'close':t.status==='已阻塞'?'info':'flow';
export function renderTaskCard(t,expanded=false,{linked=false}={}){return `<article class="task-record" data-record-key="${esc(t.key)}"><div class="task-record-main"><span class="task-record-symbol" data-state="${t.status}">${icon(glyph(t))}</span><div class="task-record-content"><div class="task-record-title"><h2>${esc(t.name)}</h2><span class="task-state-badge" data-state="${t.status}">${esc(t.status)}</span><span class="task-type-badge" data-kind="${t.type}">${t.type}</span><span class="task-property-tag">${esc(t.property)}</span></div><p class="task-record-id">${esc(t.id)}</p><p class="task-record-meta">提交：${esc(t.time)} <span>·</span> 耗时：${esc(t.duration)} <span>·</span> ${esc(t.source)}${t.definitionRevision!==undefined?` <span>·</span> 配置 v${esc(t.definitionRevision)}`:''}</p>${t.reason?`<p class="task-record-problem">${icon('info')}${esc(t.reason)}</p>`:''}${t.status==='运行中'?`<div class="task-record-progress"><i><span style="width:${Math.max(0,Math.min(100,t.progress))}%"></span></i><span>${t.progress}%</span></div>`:''}</div>${linked?`<div class="task-record-actions linked-task-actions"><button class="task-view-button" data-editor="open-task" data-run-id="${esc(t.runId)}" aria-label="查看关联任务：${esc(t.name)}">${icon("chevron")}<span>查看任务</span></button></div>`:`<div class="task-record-actions"><button class="task-view-button" data-task-op="view" data-key="${esc(t.key)}" aria-label="查看任务：${esc(t.name)}" title="查看任务"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg></button><button data-task-op="remove" data-key="${esc(t.key)}" aria-label="移除任务：${esc(t.name)}" title="从列表移除，可恢复">${icon('trash')}</button><button data-task-op="detail" data-key="${esc(t.key)}" aria-label="任务详情：${esc(t.name)}" title="任务详情">${icon('chevron')}</button></div>`}</div>${linked?`<details class="task-record-parameters linked-task-snapshot"><summary>查看输入快照${icon("chevron")}</summary><pre>${esc(JSON.stringify(t.params,null,2))}</pre></details>`:`<div class="task-record-parameters"><button data-task-op="params" data-key="${esc(t.key)}" aria-expanded="${expanded}">查看参数${icon('chevron')}</button>${expanded?`<pre>${esc(JSON.stringify(t.params,null,2))}</pre>`:''}</div>`}</article>`;}
